import sys

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    if not data: return
    n,q=data[:2]; p=2
    parent=list(range(n)); sz=[1]*n; lo=list(range(n)); hi=list(range(n)); color=list(range(1,n+1)); cnt=[0]+[1]*n
    def find(x):
        while parent[x]!=x:
            parent[x]=parent[parent[x]]; x=parent[x]
        return x
    def union(a,b):
        a=find(a); b=find(b)
        if a==b: return a
        if sz[a]<sz[b]: a,b=b,a
        parent[b]=a; sz[a]+=sz[b]; lo[a]=min(lo[a],lo[b]); hi[a]=max(hi[a],hi[b])
        return a
    out=[]
    for _ in range(q):
        t=data[p]; p+=1
        if t==1:
            x=data[p]-1; c=data[p+1]; p+=2
            r=find(x); old=color[r]
            if old!=c:
                cnt[old]-=sz[r]; cnt[c]+=sz[r]; color[r]=c
                left=lo[r]-1
                if left>=0:
                    z=find(left)
                    if color[z]==c: r=union(r,z)
                right=hi[r]+1
                if right<n:
                    z=find(right)
                    if color[z]==c: r=union(r,z)
        else:
            c=data[p]; p+=1; out.append(str(cnt[c]))
    sys.stdout.write('\n'.join(out))

if __name__=='__main__': main()

