from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        at = [[] for _ in range(n + 1)]
        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            at[b].append((a, i))

        top = (-1, -1)
        second = (-1, -1)
        gains = [0] * len(conflictingPairs)
        base = 0

        for r in range(1, n + 1):
            for item in at[r]:
                if item[0] > top[0]:
                    second = top
                    top = item
                elif item[0] > second[0]:
                    second = item

            base += r - max(0, top[0])
            if top[1] >= 0:
                gains[top[1]] += max(0, top[0] - max(0, second[0]))

        return base + max(gains)

