n=data[0]; a=[0]+data[1:]
# next occurrence
nxt=[n+1]*(n+1); last=[n+1]*(n+1)
for p in range(n,0,-1):
    nxt[p]=last[a[p]]
    last[a[p]]=p
suf=[0]*(n+2); seen=set()
for p in range(n,0,-1):
    seen.add(a[p]); suf[p]=len(seen)
# tree on indices 1..n-1
size=n-1
NEG=-10**9
t=[NEG]*(4*size); lazy=[0]*(4*size)
def build(v,l,r,vals):
    if l==r: t[v]=vals[l]; return
    m=(l+r)//2; build(v*2,l,m,vals); build(v*2+1,m+1,r,vals); t[v]=max(t[v*2],t[v*2+1])
def apply(v,x): t[v]+=x; lazy[v]+=x
def push(v):
    if lazy[v]:
        apply(v*2,lazy[v]); apply(v*2+1,lazy[v]); lazy[v]=0
def add(v,l,r,ql,qr,x):
    if ql>r or qr<l:return
    if ql<=l and r<=qr: apply(v,x); return
    push(v); m=(l+r)//2
    add(v*2,l,m,ql,qr,x); add(v*2+1,m+1,r,ql,qr,x)
    t[v]=max(t[v*2],t[v*2+1])
def setpoint(v,l,r,p,x):
    if l==r: t[v]=x; lazy[v]=0; return
    push(v); m=(l+r)//2
    if p<=m:setpoint(v*2,l,m,p,x)
    else:setpoint(v*2+1,m+1,r,p,x)
    t[v]=max(t[v*2],t[v*2+1])
def query(v,l,r,ql,qr):
    if ql<=l and r<=qr:return t[v]
    push(v); m=(l+r)//2; ans=NEG
    if ql<=m:ans=max(ans,query(v*2,l,m,ql,qr))
    if qr>m:ans=max(ans,query(v*2+1,m+1,r,ql,qr))
    return ans
vals=[0]*(n)
d=0; seen=set()
for j in range(2,n):
    if a[j] not in seen: seen.add(a[j]); d+=1
    vals[j]=d+suf[j+1]
build(1,1,size,vals)
pref=0; seen=set(); ans=0
for i in range(1,n-1):
    if a[i] not in seen: seen.add(a[i]); pref+=1
    ans=max(ans,pref+query(1,1,size,i+1,n-1))
    if i<n-2:
        setpoint(1,1,size,i+1,NEG)
        end=min(n-1,nxt[i+1]-1)
        if i+2<=end:add(1,1,size,i+2,end,-1)
