def main():
    d=list(map(int,sys.stdin.buffer.read().split())); n,x=d[:2]; k=2; ms=[]
    for _ in range(n):
        a,p,b,q=d[k:k+4]; k+=4; g=math.gcd(a,b); sc=b//g; tc=a//g
        # If S bundle is cheaper, bound T; otherwise bound S.
        if sc*p <= tc*q: ms.append((a,p,b,q,1,tc))
        else: ms.append((a,p,b,q,0,sc))
    def ok(w):
        total=0
        for a,p,b,q,mode,lim in ms:
