                for s in range(lim):
                    rem=w-a*s; t=max(0,(rem+b-1)//b); best=min(best,s*p+t*q)
            else:
                for t in range(lim):
                    rem=w-b*t; s=max(0,(rem+a-1)//a); best=min(best,t*q+s*p)
            total+=best
            if total>x: return False
        return True
    lo=0; hi=x*100+1
    while lo+1<hi:
        mid=(lo+hi)//2
        if ok(mid): lo=mid
        else: hi=mid
