class Solution:
    def numberOfWays(self, n: int, x: int, y: int) -> int:
        MOD = 10**9 + 7
        dp = [0] * (min(n, x) + 1)
        dp[0] = 1
        for i in range(1, n + 1):
            for k in range(min(i, x), 0, -1):
                dp[k] = (dp[k] * k + dp[k - 1]) % MOD
            dp[0] = 0
        ans = 0
        choose = 1
        ypow = 1
        for k in range(0, min(n, x) + 1):
            if k:
                choose = choose * (x - k + 1) % MOD
                ypow = ypow * y % MOD
            ans = (ans + dp[k] * choose % MOD * ypow) % MOD
        return ans

