class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        n = len(s)

        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i % MOD
        invfact = [1] * (n + 1)
        invfact[n] = pow(fact[n], MOD - 2, MOD)
        for i in range(n, 0, -1):
            invfact[i - 1] = invfact[i] * i % MOD

        def comb(a, b):
            if b < 0 or b > a:
                return 0
            return fact[a] * invfact[b] % MOD * invfact[a - b] % MOD

        # For a number with j set bits, the first operation gives j.
        # It is reducible in at most k steps iff j itself reaches 1
        # in at most k-1 further steps.
        valid = [False] * (n + 1)
        for j in range(1, n + 1):
            x = j
            steps = 0
            while x > 1:
                x = x.bit_count()
                steps += 1
            valid[j] = steps <= k - 1

        ans = 0
        # Count numbers strictly smaller than s, grouped by popcount.
        for j in range(1, n + 1):
            if not valid[j]:
                continue
            ones_so_far = 0
            count = 0
            for i, bit in enumerate(s):
                if bit == '1':
                    count += comb(n - i - 1, j - ones_so_far)
                    ones_so_far += 1
            ans = (ans + count) % MOD
        return ans

