import sys
from collections import deque

def main():
    input = sys.stdin.buffer.readline
    n = int(input())
    g = [input().strip().decode() for _ in range(n)]

    inc = [[[] for _ in range(26)] for _ in range(n)]
    out = [[[] for _ in range(26)] for _ in range(n)]
    for a in range(n):
        for b, ch in enumerate(g[a]):
            if ch != '-':
                c = ord(ch) - 97
                out[a][c].append(b)
                inc[b][c].append(a)

    d = [[-1] * n for _ in range(n)]
    q = deque()
    remaining = n * n
    for i in range(n):
        d[i][i] = 0
        q.append((i, i))
        remaining -= 1
    for i in range(n):
        for j in range(n):
            if i != j and g[i][j] != '-':
                d[i][j] = 1
                q.append((i, j))
                remaining -= 1

    while q and remaining:
        i, j = q.popleft()
        nd = d[i][j] + 2
        for c in range(26):
            left = inc[i][c]
            right = out[j][c]
            for a in left:
                row = d[a]
                for b in right:
                    if row[b] < 0:
                        row[b] = nd
                        remaining -= 1
                        q.append((a, b))

    sys.stdout.write('\n'.join(' '.join(map(str, row)) for row in d))

if __name__ == '__main__':
    main()

