   d0.append(min(z[0]+z[1]+mn[2],z[0]+z[2]+mn[1],z[1]+z[2]+mn[0]))
   d1.append(min(o[0]+o[1]+mn[2],o[0]+o[2]+mn[1],o[1]+o[2]+mn[0]))
  c0,c1=d0,d1
