def fast(s, queries):
 n=len(s); p1=[0]*(n+1);p2=[0]*(n+1);v=[]
 from bisect import bisect_left
 for i,c in enumerate(s):
  p1[i+1]=p1[i]+(c=='1');p2[i+1]=p2[i]+(c=='2')
  if c=='/':v.append(i)
 ans=[]
 for L,R in queries:
  l=L-1;r=R-1;a=bisect_left(v,l);b=bisect_left(v,r+1)
  lo,hi=a,b
  while lo<hi:
   m=(lo+hi)//2;i=v[m]
   if p1[i]-p1[l]>=p2[r+1]-p2[i+1]:hi=m
   else:lo=m+1
  z=0
  for j in (lo-1,lo):
   if a<=j<b:
    i=v[j];z=max(z,min(p1[i]-p1[l],p2[r+1]-p2[i+1]))
  ans.append(2*z+1 if b>a else 0)
 return ans

