    def permute(self, n: int, k: int) -> List[int]:
        odds = [x for x in range(1, n + 1, 2)]
        evens = [x for x in range(2, n + 1, 2)]
        ans = []
        prev = None

        for pos in range(n):
            chosen = False
            for x in sorted(odds + evens):
                p = x % 2
                if prev is not None and p == prev:
                    continue

                ro = len(odds) - (p == 1)
                re = len(evens) - (p == 0)
                m = n - pos - 1
                if m:
                    first = 1 - p
                    need_first = (m + 1) // 2
                    need_other = m // 2
                    expected = ((need_first, need_other) if first == 1
                                else (need_other, need_first))
                    if (ro, re) != expected:
                        continue
                elif ro or re:
                    continue

                block = factorial(ro) * factorial(re)
                if k > block:
                    k -= block
                else:
                    ans.append(x)
                    if p:
                        odds.remove(x)
                    else:
                        evens.remove(x)
                    prev = p
                    chosen = True
                    break

            if not chosen:
                return []

        return ans

