class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        h = (n + 1) // 2
        weights = []
        p10 = [1] * n
        for i in range(1, n):
            p10[i] = p10[i - 1] * 10 % k
        for i in range(h):
            j = n - 1 - i
            w = p10[i] if i == j else (p10[i] + p10[j]) % k
            weights.append(w)
        dp = [0] * (h + 1)
        dp[h] = 1
        for i in range(h - 1, -1, -1):
            mask = 0
            lo = 1 if i == 0 else 0
            for r in range(k):
                if dp[i + 1] >> r & 1:
                    for d in range(lo, 10):
                        mask |= 1 << ((r + d * weights[i]) % k)
            dp[i] = mask
        chosen = []
        rem = 0
        for i, w in enumerate(weights):
            lo = 1 if i == 0 else 0
            for d in range(9, lo - 1, -1):
                need = (-rem - d * w) % k
                if dp[i + 1] >> need & 1:
                    chosen.append(str(d))
                    rem = (rem + d * w) % k
                    break
        half = ''.join(chosen)
        return half + (half[:-1][::-1] if n % 2 else half[::-1])

