class Solution:
 def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
  n=len(nums); blocks=deque(); cost=0; r=n-1; ans=0
  for l in range(n-1,-1,-1):
   x=nums[l]; cnt=1; sm=x
   while blocks and blocks[0][0] <= x:
    h,c,s=blocks.popleft(); cost += x*c-s; cnt+=c; sm+=s
   blocks.appendleft([x,cnt,sm])
   while cost>k:
    h,c,s=blocks[-1]
    cost -= h-nums[r]
    c-=1; s-=nums[r]; r-=1
    if c: blocks[-1]=[h,c,s]
    else: blocks.pop()
   ans += r-l+1
  return ans

