from typing import List

class Solution:
    def maximizeSumOfWeights(self, edges: List[List[int]], k: int) -> int:
        n = len(edges) + 1
        graph = [[] for _ in range(n)]
        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))

        parent = [-1] * n
        parent[0] = 0
        order = [0]
        for u in order:
            for v, w in graph[u]:
                if v != parent[u]:
                    parent[v] = u
                    order.append(v)

        dp_without_parent = [0] * n
        dp_with_parent = [0] * n
        for u in reversed(order):
            base = 0
            gains = []
            for v, w in graph[u]:
                if parent[v] == u:
                    base += dp_without_parent[v]
                    gains.append(w + dp_with_parent[v] - dp_without_parent[v])
            gains.sort(reverse=True)
            positive_gains = [gain for gain in gains if gain > 0]
            dp_without_parent[u] = base + sum(positive_gains[:k])
            dp_with_parent[u] = base + sum(positive_gains[:max(0, k - 1)])

        return dp_without_parent[0]

