import sys
class BIT:
 def __init__(self,n): self.n=n; self.t=[0]*(n+1); self.sz=0
 def add(self,x,d):
  self.sz+=d
  while x<=self.n:self.t[x]+=d;x+=x&-x
 def s(self,x):
  z=0
  while x:z+=self.t[x];x-=x&-x
  return z
 def less(self,x):return self.s(x-1)
 def greater(self,x):return self.sz-self.s(x)
def solve():
 d=list(map(int,sys.stdin.buffer.read().split())); n,k=d[:2];p=d[2:]
 pref=[0]*(n+1);bt=BIT(n)
 for i,x in enumerate(p):pref[i+1]=pref[i]+bt.greater(x);bt.add(x,1)
 total=pref[n];suff=[0]*(n+1);bt=BIT(n)
 for i in range(n-1,-1,-1):suff[i]=suff[i+1]+bt.less(p[i]);bt.add(p[i],1)
 W=BIT(n);A=BIT(n);B=BIT(n)
 for x in p[:k]:W.add(x,1)
 for x in p[k:]:B.add(x,1)
 L=0;R=sum(W.greater(x) for x in p[k:]);count=n-k+1;ans=0
 for l in range(count):
  outside=total-pref[l]-suff[l+k]
  ans=(ans+2*(outside+L+R)+k*(k-1)//2)%MOD
  if l+1==count:break
  a=p[l];b=p[l+k]
  L+=A.greater(b)-A.greater(a)+W.less(a)+(b<a)
  R+=B.less(a)-B.less(b)-(W.greater(b)-(a>b))
  A.add(a,1);W.add(a,-1);B.add(b,-1);W.add(b,1)
 print(ans*pow(2*count,MOD-2,MOD)%MOD)
solve()

